window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-ffacec7dc58dfc72"]={"versions": [{"id": "FIG-ffacec7dc58dfc72", "releases": ["R3.0.7", "R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Zustandsdiagramm (<code>stm CONTINUOUS_SINGLE-ACCESS</code>) für den AUTOSAR-Treiber für Analog-Digital-Wandler (<code>ADC_Driver</code>) innerhalb der Microcontroller Abstraction Layer (MCAL). Das Diagramm modelliert das Zustandsverhalten einer ADC-Kanalgruppe unter der spezifischen Konfiguration: kontinuierliche Konvertierung (<code>continuous conversion</code>), Software-Triggerung (<code>software trigger source</code>) und Einzelzugriffspufferung (<code>single access</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Zustände:</strong></li>\n<li>Initialzustand (schwarzer Vollkreis / Pseudozustand)</li>\n<li><code>ADC_IDLE</code>: Ruhezustand der ADC-Gruppe.</li>\n<li><code>ADC_BUSY</code>: Konvertierungsphase der Kanalgruppe.</li>\n<li><code>ADC_STREAM_COMPLETED</code>: Status nach Abschluss eines Konvertierungsdurchlaufs aller Gruppenkanäle.</li>\n<li><strong>API-Funktionen / Trigger / Events:</strong></li>\n<li><code>Adc_StartGroupConversion</code>: Startet die kontinuierliche Konvertierung einer Gruppe.</li>\n<li><code>Adc_StopGroupConversion</code>: Bricht die laufende Konvertierung ab bzw. stoppt die Gruppe.</li>\n<li><code>Adc_ReadGroup</code>: Liest die zuletzt gewandelten Ergebnisse der Kanalgruppe aus.</li>\n<li><code>Adc_GetStreamLastPointer</code>: Ruft den Zeiger auf das zuletzt gefüllte Resultat-Array ab.</li>\n<li>Internes Ereignis: <code>conversion of all group channels completed</code>.</li>\n<li><strong>Konfigurationsnotiz:</strong></li>\n<li><code>ADC group configuration: - continuous conversion - software trigger source - single access</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Aus dem Initialzustand wechselt die Zustandsmaschine unkonditioniert in den Zustand <code>ADC_IDLE</code>.</li>\n<li>Im Zustand <code>ADC_IDLE</code> können Selbstübergänge über <code>Adc_ReadGroup</code> oder <code>Adc_GetStreamLastPointer</code> erfolgen, ohne den Zustand zu verlassen.</li>\n<li>Der Aufruf von <code>Adc_StartGroupConversion</code> triggert die Transition von <code>ADC_IDLE</code> nach <code>ADC_BUSY</code>.</li>\n<li>In <code>ADC_BUSY</code> führen Aufrufe von <code>Adc_ReadGroup</code> oder <code>Adc_GetStreamLastPointer</code> zu Selbstübergängen. Ein Aufruf von <code>Adc_StopGroupConversion</code> führt direkt zurück in den Zustand <code>ADC_IDLE</code>.</li>\n<li>Bei Abschluss eines Konvertierungszyklus aller Kanäle der Gruppe (<code>conversion of all group channels completed</code>) wechselt der Zustand von <code>ADC_BUSY</code> nach <code>ADC_STREAM_COMPLETED</code>.</li>\n<li>Aus <code>ADC_STREAM_COMPLETED</code> führt:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>der Aufruf von <code>Adc_GetStreamLastPointer</code> oder <code>Adc_ReadGroup</code> zurück in den Zustand <code>ADC_BUSY</code>, wodurch die kontinuierliche Wandlung fortgeführt wird.</li>\n<li>der Aufruf von <code>Adc_StopGroupConversion</code> direkt in den Ruhezustand <code>ADC_IDLE</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Zustandsdiagramm spezifiziert das Sollverhalten für MCAL-Treiber-Implementierungen bei Software-getriggerten kontinuierlichen Wandlungen mit einfachem Zugriffspuffer. Wesentlich ist, dass nach Vollendung eines Durchlaufs (<code>ADC_STREAM_COMPLETED</code>) die Gruppe erst durch das Auslesen der Daten via <code>Adc_ReadGroup</code> oder <code>Adc_GetStreamLastPointer</code> wieder in <code>ADC_BUSY</code> übergeht bzw. der Wandlungsstrom verarbeitet werden kann, oder durch <code>Adc_StopGroupConversion</code> gestoppt werden muss. Entwickler müssen sicherstellen, dass Pufferüberläufe vermieden werden und das Stoppen (<code>Adc_StopGroupConversion</code>) aus beiden aktiven Zuständen (<code>ADC_BUSY</code>, <code>ADC_STREAM_COMPLETED</code>) synchron bzw. sauber den Ruhezustand <code>ADC_IDLE</code> wiederherstellt.</p>"}, {"id": "FIG-60deeb52e124a012", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Zustandsdiagramm (<code>stm CONTINUOUS_SINGLE-ACCESS</code>) für den AUTOSAR-Treiber für Analog-Digital-Wandler (<code>ADC_Driver</code>) innerhalb der Microcontroller Abstraction Layer (MCAL). Das Diagramm modelliert das Zustandsverhalten einer ADC-Kanalgruppe unter der spezifischen Konfiguration: kontinuierliche Konvertierung (<code>continuous conversion</code>), Software-Triggerung (<code>software trigger source</code>) und Einzelzugriffspufferung (<code>single access</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Zustände:</strong></li>\n<li>Initialzustand (schwarzer Vollkreis / Pseudozustand)</li>\n<li><code>ADC_IDLE</code>: Ruhezustand der ADC-Gruppe.</li>\n<li><code>ADC_BUSY</code>: Konvertierungsphase der Kanalgruppe.</li>\n<li><code>ADC_STREAM_COMPLETED</code>: Status nach Abschluss eines Konvertierungsdurchlaufs aller Gruppenkanäle.</li>\n<li><strong>API-Funktionen / Trigger / Events:</strong></li>\n<li><code>Adc_StartGroupConversion</code>: Startet die kontinuierliche Konvertierung einer Gruppe.</li>\n<li><code>Adc_StopGroupConversion</code>: Bricht die laufende Konvertierung ab bzw. stoppt die Gruppe.</li>\n<li><code>Adc_ReadGroup</code>: Liest die zuletzt gewandelten Ergebnisse der Kanalgruppe aus.</li>\n<li><code>Adc_GetStreamLastPointer</code>: Ruft den Zeiger auf das zuletzt gefüllte Resultat-Array ab.</li>\n<li>Internes Ereignis: <code>conversion of all group channels completed</code>.</li>\n<li><strong>Konfigurationsnotiz:</strong></li>\n<li><code>ADC group configuration: - continuous conversion - software trigger source - single access</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Aus dem Initialzustand wechselt die Zustandsmaschine unkonditioniert in den Zustand <code>ADC_IDLE</code>.</li>\n<li>Im Zustand <code>ADC_IDLE</code> können Selbstübergänge über <code>Adc_ReadGroup</code> oder <code>Adc_GetStreamLastPointer</code> erfolgen, ohne den Zustand zu verlassen.</li>\n<li>Der Aufruf von <code>Adc_StartGroupConversion</code> triggert die Transition von <code>ADC_IDLE</code> nach <code>ADC_BUSY</code>.</li>\n<li>In <code>ADC_BUSY</code> führen Aufrufe von <code>Adc_ReadGroup</code> oder <code>Adc_GetStreamLastPointer</code> zu Selbstübergängen. Ein Aufruf von <code>Adc_StopGroupConversion</code> führt direkt zurück in den Zustand <code>ADC_IDLE</code>.</li>\n<li>Bei Abschluss eines Konvertierungszyklus aller Kanäle der Gruppe (<code>conversion of all group channels completed</code>) wechselt der Zustand von <code>ADC_BUSY</code> nach <code>ADC_STREAM_COMPLETED</code>.</li>\n<li>Aus <code>ADC_STREAM_COMPLETED</code> führt:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>der Aufruf von <code>Adc_GetStreamLastPointer</code> oder <code>Adc_ReadGroup</code> zurück in den Zustand <code>ADC_BUSY</code>, wodurch die kontinuierliche Wandlung fortgeführt wird.</li>\n<li>der Aufruf von <code>Adc_StopGroupConversion</code> direkt in den Ruhezustand <code>ADC_IDLE</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Zustandsdiagramm spezifiziert das Sollverhalten für MCAL-Treiber-Implementierungen bei Software-getriggerten kontinuierlichen Wandlungen mit einfachem Zugriffspuffer. Wesentlich ist, dass nach Vollendung eines Durchlaufs (<code>ADC_STREAM_COMPLETED</code>) die Gruppe erst durch das Auslesen der Daten via <code>Adc_ReadGroup</code> oder <code>Adc_GetStreamLastPointer</code> wieder in <code>ADC_BUSY</code> übergeht bzw. der Wandlungsstrom verarbeitet werden kann, oder durch <code>Adc_StopGroupConversion</code> gestoppt werden muss. Entwickler müssen sicherstellen, dass Pufferüberläufe vermieden werden und das Stoppen (<code>Adc_StopGroupConversion</code>) aus beiden aktiven Zuständen (<code>ADC_BUSY</code>, <code>ADC_STREAM_COMPLETED</code>) synchron bzw. sauber den Ruhezustand <code>ADC_IDLE</code> wiederherstellt.</p>"}], "trans": [{"from": "FIG-ffacec7dc58dfc72", "to": "FIG-60deeb52e124a012", "fr": "R3.1.5", "tr": "R3.2.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
